#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

void countingSort(vector<int>& arr) {
    int n = arr.size(), mx = *max_element(arr.begin(), arr.end());
    vector<int> cnt(mx + 1, 0);
    for (int v : arr) cnt[v]++;
    for (int i = 1; i <= mx; i++) cnt[i] += cnt[i - 1];
    vector<int> out(n);
    for (int i = n - 1; i >= 0; i--) out[--cnt[arr[i]]] = arr[i];
    arr = out;
}

int main() {
    vector<int> a = {4, 2, 2, 8, 3, 3, 1};
    countingSort(a);
    for (int v : a) cout << v << " ";
    return 0;
}
